from collections import Counter

def transform(grid):
    a=[r[:] for r in grid]; H=len(a); W=len(a[0]); bg=Counter(x for r in a for x in r).most_common(1)[0][0]
    splitrows=[i for i,r in enumerate(a) if all(x==bg for x in r)]
    splitcols=[j for j in range(W) if all(a[i][j]==bg for i in range(H))]
    def segments(v,n):
        out=[]; s=0
        for x in v+[n]:
            if s<x: out.append((s,x))
            s=x+1
        return out
    rs=segments(splitrows,H); cs=segments(splitcols,W)
    for r0,r1 in rs:
      for c0,c1 in cs:
        if r1-r0<3 or c1-c0<3: continue
        arr=[r[c0+1:c1-1] for r in a[r0+1:r1-1]]
        h=len(arr); w=len(arr[0]); vertical=h>=w; L=h if vertical else w
        best=None
        for p in range(1,L//2+1):
            vals=[]
            for k in range(p):
                inds=list(range(k,L,p))
                if vertical:
                    phase=[Counter(arr[i][j] for i in inds).most_common(1)[0][0] for j in range(w)]
                else:
                    phase=[Counter(arr[i][j] for j in inds).most_common(1)[0][0] for i in range(h)]
                vals.append(phase)
            err=0
            for i in range(h):
              for j in range(w):
                target=vals[i%p][j] if vertical else vals[i][j%p]
                err+=arr[i][j]!=target
            if best is None or err<best[0]: best=(err,p,vals)
        err,p,vals=best
        for i in range(h):
          for j in range(w):
            arr[i][j]=vals[i%p][j] if vertical else vals[i][j%p]
        for i in range(h): a[r0+1+i][c0+1:c1-1]=arr[i]
    return a
